css:
.gx-invoice { font-size: 12px; line-height: 1.4; color: #111; }
.gx-invoice table { width: 100%; border-collapse: collapse; }
.gx-invoice td, .gx-invoice th { padding: 0; vertical-align: top; }
.gx-invoice p { margin: 0; }
.gx-top td { padding-bottom: 12px; }
.gx-company { font-size: 16px; font-weight: bold; margin-bottom: 4px; }
.gx-title { width: 35%; text-align: right; }
.gx-heading { font-size: 18px; font-weight: bold; margin-bottom: 4px; }
.gx-parties { border-top: 1px solid #999; }
.gx-parties td { padding: 10px 0 12px; }
.gx-parties td.gx-supply { width: 35%; text-align: right; }
.gx-label { color: #555; font-size: 11px; }
.gx-label-gap { margin-top: 6px; }
.gx-items th { border-top: 1px solid #999; border-bottom: 1px solid #999; padding: 5px 4px; text-align: left; font-size: 11px; }
.gx-items td { border-bottom: 1px solid #ddd; padding: 6px 4px; }
.gx-items .gx-num { text-align: right; white-space: nowrap; }
.gx-totals { width: 50% !important; margin: 10px 0 0 50%; }
.gx-totals td { padding: 3px 4px; }
.gx-totals td.gx-num { text-align: right; white-space: nowrap; }
.gx-totals tr.gx-grand td { border-top: 1px solid #999; font-weight: bold; padding-top: 6px; }
.gx-words { margin-top: 12px !important; }
.gx-status { margin-top: 6px !important; font-weight: bold; }
.gx-note { margin-top: 18px !important; color: #555; font-size: 11px; }
